const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.postedJobLinks)) staticData.postedJobLinks = [];
const posted = new Set(staticData.postedJobLinks);
const fresh = $input.all().map(i => i.json).filter(j => j.link && !posted.has(j.link));
if (!fresh.length) return [];
const item = fresh[0]; // feed is newest-first
return [{ json: { title: item.title || '', link: item.link, pubDate: item.pubDate || item.isoDate || '' } }];

const raw = $json.data || '';
let text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 8000);
const picked = $('Pick New Circular').first().json;
const systemPrompt = `তুমি Questionhut নামের একটি বাংলাদেশি ফেসবুক পেজের সোশ্যাল মিডিয়া ম্যানেজার। পেজের অডিয়েন্স চাকরিপ্রার্থী। নিচে একটি চাকরির বিজ্ঞপ্তির (job circular) ওয়েবপেজ থেকে নেওয়া টেক্সট দেওয়া হবে। সেটির ভিত্তিতে একটি আকর্ষণীয় ফেসবুক পোস্ট বাংলায় লেখো। নিয়ম: (১) শুধুমাত্র দেওয়া টেক্সটে থাকা তথ্য ব্যবহার করবে, নিজে থেকে কোনো তথ্য (তারিখ, পদসংখ্যা, বেতন) বানাবে না; কোনো তথ্য না থাকলে সেটি বাদ দেবে। (২) থাকলে উল্লেখ করবে: প্রতিষ্ঠানের নাম, পদের নাম ও সংখ্যা, শিক্ষাগত যোগ্যতা, আবেদনের শেষ তারিখ, আবেদনের মাধ্যম। (৩) শুরুতে একটি চোখে পড়ার মতো লাইন ও প্রাসঙ্গিক ইমোজি ব্যবহার করবে, বুলেট আকারে গুছিয়ে লিখবে। (৪) শেষে ৩-৪টি হ্যাশট্যাগ দেবে যেমন #চাকরির_খবর #JobCircular #Questionhut। (৫) মার্কডাউন ফরম্যাটিং (** বা #) ব্যবহার করবে না, ফেসবুকে এগুলো কাজ করে না; ইমোজি ও সাধারণ টেক্সট ব্যবহার করবে। (৬) যদি বিজ্ঞপ্তিতে অনেকগুলো পদ/তারিখ/সংখ্যা থাকে, সেগুলো একসাথে জোড়া না দিয়ে সংক্ষেপে লিখবে (যেমন: "বিভিন্ন জেলায় একাধিক পদ", "জেলাভেদে ভিন্ন, বিস্তারিত লিংকে")। (৭) লিংক লিখবে না, সেটা আলাদাভাবে যোগ হবে। শুধুমাত্র বৈধ JSON দেবে: {"message":"..."}`;
const userPrompt = `বিজ্ঞপ্তির শিরোনাম: ${picked.title}\n\nওয়েবপেজের টেক্সট:\n${text}`;
return [{ json: { systemPrompt, userPrompt } }];

const resp = $json;
let content = resp.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('OpenAI returned non-JSON: ' + content.slice(0, 200)); }
if (!parsed.message) throw new Error('No message field in OpenAI response');
const picked = $('Pick New Circular').first().json;
const message = parsed.message.trim() + '\n\n👉 বিস্তারিত দেখুন ও আবেদন করুন: ' + picked.link;
return [{ json: { message, link: picked.link } }];

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.postedJobLinks)) staticData.postedJobLinks = [];
const link = $('Pick New Circular').first().json.link;
if (!staticData.postedJobLinks.includes(link)) staticData.postedJobLinks.push(link);
if (staticData.postedJobLinks.length > 200) staticData.postedJobLinks = staticData.postedJobLinks.slice(-200);
return [{ json: { done: true, postedLink: link, fbPostId: $json.id || $json.post_id || null } }];
